select id, location, budget, min(budget) over w_ordered running_min_budget, sum(budget) over w_ordered running_sum_budget, count(budget) over w_ordered running_count_budget, last_value(budget, true) over (order by budget, id rows between unbounded preceding and current row) last_known_budget from departments window w_ordered as (partition by location order by budget, id rows between unbounded preceding and current row)
